<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';$editando=isset($producto);?><main class="container-fluid py-4 px-lg-4"><div class="col-xl-8"><h2><?=$editando?'Editar':'Nuevo'?> producto</h2><form method="post" class="card p-4"><div class="row g-3"><div class="col-md-6"><label class="form-label">Campaña</label><select class="form-select" name="campania_id" required><option value="">Seleccionar...</option><?php foreach($campanias as $c):?><option value="<?=$c['id']?>" <?=($editando&&$producto['campania_id']==$c['id'])?'selected':''?>><?=e($c['nombre'])?> (<?=e($c['estado'])?>)</option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Nombre</label><input class="form-control" name="nombre" value="<?=e($editando?$producto['nombre']:'')?>" required></div><div class="col-12"><label class="form-label">Descripción</label><textarea class="form-control" name="descripcion"><?=e($editando?$producto['descripcion']:'')?></textarea></div><div class="col-md-4"><label class="form-label">Precio</label><input class="form-control" type="number" step="0.01" min="0" name="precio" value="<?=e($editando?$producto['precio']:'')?>" required></div><?php if(!$editando):?><div class="col-md-4"><label class="form-label">Stock inicial</label><input class="form-control" type="number" min="0" name="stock" required></div><?php endif;?><div class="col-md-4"><label class="form-label">Stock mínimo</label><input class="form-control" type="number" min="0" name="stock_minimo" value="<?=e($editando?$producto['stock_minimo']:5)?>" required></div><?php if($editando):?><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="activo" id="activo" <?=$producto['activo']?'checked':''?>><label class="form-check-label" for="activo">Producto activo</label></div><?php endif;?></div><div class="mt-4"><button class="btn btn-primary">Guardar</button><a class="btn btn-light" href="index.php?c=producto&a=inicio">Cancelar</a></div></f